import React, { useState, useEffect } from "react";
import { MapContainer, TileLayer, GeoJSON } from "react-leaflet";
import "leaflet/dist/leaflet.css";
import Slider from "react-slider";
import "./App.css";

function App() {
  const [year, setYear] = useState(2012);
  const [geoData, setGeoData] = useState(null);
  const [activeDataType, setActiveDataType] = useState("Победитель");
  const [activeElectionLevel, setActiveElectionLevel] = useState("Госдума");

  useEffect(() => {
    fetch(`/data/elections-${year}.geojson`)
      .then((res) => res.json())
      .then((data) => setGeoData(data))
      .catch((err) => console.error("Ошибка загрузки GeoJSON:", err));
  }, [year]);

  return (
    <div className="App">
      <h1>Геопортал: Выборы в Москве</h1>

      {/* Слайдер */}
      <div className="slider-container">
        <label>Год: {year}</label>
        <Slider
          className="slider"
          value={year}
          min={2012}
          max={2022}
          step={1}
          onChange={setYear}
          renderTrack={(props) => <div {...props} className="slider-track" />}
          renderThumb={(props) => <div {...props} className="slider-thumb" />}
        />
      </div>

      {/* Карта + панели */}
      <div className="map-wrapper">
        <div className="map-container">
          {/* Верхняя панель */}
          <div className="top-controls">
            {["Явка", "Победитель", "Процент испорченных бюллетеней"].map(
              (label) => (
                <button
                  key={label}
                  className={activeDataType === label ? "active" : ""}
                  onClick={() => setActiveDataType(label)}
                >
                  {label}
                </button>
              )
            )}
          </div>
		{activeElectionLevel === "Госдума" && (
		  <div className="center-controls">
			<button>Округ</button>
			<button>Список</button>
		  </div>
		)}
          {/* Боковая панель */}
          <div className="controls">
            {["Госдума", "Мосгордума", "Муниципальные", "Мэр", "Президент"].map(
              (label) => (
                <button
                  key={label}
                  className={activeElectionLevel === label ? "active" : ""}
                  onClick={() => setActiveElectionLevel(label)}
                >
                  {label}
                </button>
              )
            )}
          </div>

          {/* Leaflet карта */}
          <MapContainer
            center={[55.7558, 37.6173]}
            zoom={10}
            className="map-container"
          >
            <TileLayer
              attribution='&copy; <a href="http://osm.org/copyright">OpenStreetMap</a>'
              url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
            />
            {geoData && (
              <GeoJSON
                data={geoData}
                style={() => ({
                  color: "#007bff",
                  weight: 1,
                  fillOpacity: 0.25,
                })}
                onEachFeature={(feature, layer) => {
                  const props = feature.properties;
                  const label = props?.name || props?.id || "Участок";
                  layer.bindPopup(`<b>${label}</b>`);
                }}
              />
            )}
          </MapContainer>
        </div>
      </div>
    </div>
  );
}

export default App;
